const saaTbody = document.getElementById('saaRows');
const saaEmptyEl = document.getElementById('saaEmpty');
const saaBubbleEl = document.getElementById('saaBubble');
const saaQEcho = document.getElementById('saaQEcho');
const saaCountEl = document.getElementById('saaCount');
const saaSearchInput = document.getElementById('saaQ');
const saaHofToggle = document.getElementById('saaHofOnly');
const saaHofMissingToggle = document.getElementById('saaHofMissing');
const saaHeaders = Array.from(document.querySelectorAll('.saa-embed th[data-key]'));

let saaSortKey = 'rank';
let saaSortDir = 1; // 1 asc, -1 desc
let saaQuery = '';
const saaExpanded = new Set(); // SAA ranks whose career card is open

// ---- remembered view (js/prefs.js): sort + search + HoF toggle ----
const SAA_PREF_KEY = 'hitters';
const SAA_KEYS = new Set(saaHeaders.map(th => th.dataset.key));
function saaMarkSortedHeader() {
  saaHeaders.forEach(h => {
    const on = h.dataset.key === saaSortKey;
    h.classList.toggle('sorted', on);
    const arrow = h.querySelector('.arrow');
    if (on && arrow) arrow.textContent = saaSortDir === 1 ? '▲' : '▼';
  });
}
function saaSavePrefs() {
  if (!window.THOF) return;
  THOF.set(SAA_PREF_KEY, {
    sortKey: saaSortKey, sortDir: saaSortDir, q: saaQuery,
    hof: saaHofToggle.checked, hofMissing: saaHofMissingToggle.checked,
  });
}
(function saaRestorePrefs() {
  const s = window.THOF && THOF.get(SAA_PREF_KEY, null);
  if (!s) return;
  if (s.sortKey && SAA_KEYS.has(s.sortKey)) {
    saaSortKey = s.sortKey;
    saaSortDir = s.sortDir === -1 ? -1 : 1;
  }
  if (typeof s.q === 'string' && s.q) { saaQuery = s.q; saaSearchInput.value = s.q; }
  if (s.hofMissing && SAA_MISSING.length) saaHofMissingToggle.checked = true;
  if (s.hof && !saaHofMissingToggle.checked) saaHofToggle.checked = true;
  saaHofToggle.disabled = saaHofMissingToggle.checked;
  saaMarkSortedHeader();
})();

function saaFmtZ(z) {
  const cls = z > 0.15 ? 'z-pos' : (z < -0.15 ? 'z-neg' : 'z-flat');
  const txt = (z > 0 ? '+' : '') + z.toFixed(2);
  return `<td class="${cls}">${txt}</td>`;
}

// One diverging bar in the expanded card: z-score vs. league, origin at 0,
// magnitude clamped to +/-4 SD for the bar width (the number is exact).
function saaZBar(label, z) {
  const cls = z > 0.15 ? 'pos' : (z < -0.15 ? 'neg' : 'flat');
  const mag = (Math.min(Math.abs(z), 4) / 4) * 50;
  const side = z >= 0 ? 'left' : 'right';
  return `<div class="saa-card__zrow">
      <span class="saa-card__zlabel">${label}</span>
      <span class="saa-card__ztrack"><span class="saa-card__zfill ${cls}" style="${side}:50%;width:${mag}%"></span></span>
      <span class="saa-card__zval ${cls}">${z > 0 ? '+' : ''}${z.toFixed(2)}</span>
    </div>`;
}

function saaCard(d) {
  const c = SAA_CAREER[d.rank] || {};
  const dec = v => (v == null ? '—' : v.toFixed(3).replace(/^0/, ''));
  const int = v => (v == null ? '—' : v.toLocaleString('en-US'));
  const slash = [
    ['AVG', dec(c.avg)], ['OBP', dec(c.obp)], ['SLG', dec(c.slg)], ['OPS', dec(c.ops)],
    ['OPS+', c.opsPlus == null ? '—' : c.opsPlus],
    ['bWAR', c.war == null ? '—' : c.war.toFixed(1)],
  ].map(([k, v]) => `<div><b>${v}</b><span>${k}</span></div>`).join('');
  const counting = [
    ['G', c.g], ['H', c.h], ['HR', c.hr], ['RBI', c.rbi],
    ['R', c.r], ['SB', c.sb], ['BB', c.bb], ['SO', c.so],
  ].map(([k, v]) => `<span><b>${int(v)}</b> ${k}</span>`).join('');
  const meta = [c.pos, c.yrs, c.team].filter(Boolean).join(' · ');
  const nelNote = d.nel
    ? '<p class="saa-card__note">Negro Leagues seasons are part of this ranking. Official league schedules ran far shorter than the majors\' and the surviving record is incomplete, so the career counting stats read low relative to the playing time behind them.</p>'
    : '';
  return `<div class="saa-card">
      <div class="saa-card__head">
        <span class="saa-card__rank">#${d.rank}</span>
        <span class="saa-card__name">${d.name}${d.hof ? ' <span class="hof-star">★</span>' : ''}</span>
        <span class="saa-card__meta">${meta}</span>
      </div>
      <div class="saa-card__slash">${slash}</div>
      <div class="saa-card__counting">${counting}</div>
      <div class="saa-card__z">
        <div class="saa-card__z-head">
          <span class="saa-card__z-score">Stat Above Average <b>${d.saa > 0 ? '+' : ''}${d.saa.toFixed(2)}</b></span>
          ${d.total != null && d.peak != null ? `<span class="saa-card__z-math">= (career total ${d.total > 0 ? '+' : ''}${d.total.toFixed(2)} + best-7 peak ${d.peak > 0 ? '+' : ''}${d.peak.toFixed(2)}) &divide; 2</span>` : ''}
        </div>
        ${saaZBar('AVG', d.avg)}${saaZBar('ISO', d.iso)}${saaZBar('BB', d.bb)}${saaZBar('SB', d.sb)}${saaZBar('DEF', d.def)}
      </div>
      ${nelNote}
    </div>`;
}

function saaDetailRow(d) {
  return `<tr class="saa-detail"><td colspan="12">${saaCard(d)}</td></tr>`;
}

// A non-expandable row for the "Hall of Famers we leave out" view: the player's
// real SAA rank sits outside the list, so there's no career card to open.
function saaFlatRow(d) {
  return `<tr class="saa-row is-flat" data-rank="${d.rank}">
      <td class="rank">${d.rank}</td>
      <td class="saa">${d.saa > 0 ? '+' : ''}${d.saa.toFixed(2)}</td>
      <td class="name">${d.name}</td>
      <td class="nel">${d.nel ? '<span class="nel-tag">NeL</span>' : ''}</td>
      <td>${d.pa.toLocaleString('en-US')}</td>
      <td>${d.seasons}</td>
      ${saaFmtZ(d.avg)}
      ${saaFmtZ(d.iso)}
      ${saaFmtZ(d.bb)}
      ${saaFmtZ(d.sb)}
      ${saaFmtZ(d.def)}
      <td><span class="hof-star">★</span></td>
    </tr>`;
}

function saaRender() {
  const missing = saaHofMissingToggle.checked;
  let rows = missing ? SAA_MISSING : SAA_DATA;
  if (saaQuery) {
    const qq = saaQuery.toLowerCase();
    rows = rows.filter(d => d.name.toLowerCase().includes(qq));
  }
  if (!missing && saaHofToggle.checked) {
    rows = rows.filter(d => d.hof);
  }

  const sorted = rows.slice().sort((a, b) => {
    const av = a[saaSortKey], bv = b[saaSortKey];
    if (typeof av === 'string') return av.localeCompare(bv) * saaSortDir;
    if (typeof av === 'boolean') return ((av === bv) ? 0 : (av ? -1 : 1)) * saaSortDir;
    return (av - bv) * saaSortDir;
  });

  if (missing) {
    saaCountEl.textContent = saaQuery
      ? `${sorted.length} of ${SAA_MISSING.length} Hall of Fame hitters outside the top ${SAA_DATA.length}`
      : `${SAA_MISSING.length} Hall of Fame hitters qualify but rank outside the top ${SAA_DATA.length}`;
  } else {
    saaCountEl.textContent = saaQuery || saaHofToggle.checked
      ? `${sorted.length} of ${SAA_DATA.length} players`
      : `${SAA_DATA.length} players, ranked by Stat Above Average`;
  }

  if (sorted.length === 0) {
    saaTbody.innerHTML = '';
    saaEmptyEl.style.display = 'block';
    saaQEcho.textContent = saaQuery;
    return;
  }
  saaEmptyEl.style.display = 'none';

  if (missing) {
    saaTbody.innerHTML = sorted.map(saaFlatRow).join('');
    return;
  }

  saaTbody.innerHTML = sorted.map(d => {
    const open = saaExpanded.has(d.rank);
    return `<tr class="saa-row${open ? ' is-open' : ''}" data-rank="${d.rank}" tabindex="0" aria-expanded="${open}">
      <td class="rank"><span class="saa-caret">${open ? '▾' : '▸'}</span>${d.rank}</td>
      <td class="saa">${d.saa > 0 ? '+' : ''}${d.saa.toFixed(2)}</td>
      <td class="name">${d.name}</td>
      <td class="nel">${d.nel ? '<span class="nel-tag">NeL</span>' : ''}</td>
      <td>${d.pa.toLocaleString('en-US')}</td>
      <td>${d.seasons}</td>
      ${saaFmtZ(d.avg)}
      ${saaFmtZ(d.iso)}
      ${saaFmtZ(d.bb)}
      ${saaFmtZ(d.sb)}
      ${saaFmtZ(d.def)}
      <td>${d.hof ? '<span class="hof-star">★</span>' : '<span class="hof-dash">—</span>'}</td>
    </tr>${open ? saaDetailRow(d) : ''}`;
  }).join('');
}

saaHeaders.forEach(th => {
  th.addEventListener('click', () => {
    const key = th.dataset.key;
    if (saaSortKey === key) {
      saaSortDir *= -1;
    } else {
      saaSortKey = key;
      saaSortDir = 1;
    }
    saaMarkSortedHeader();
    saaRender();
    saaSavePrefs();
  });
});

saaSearchInput.addEventListener('input', e => {
  saaQuery = e.target.value.trim();
  saaRender();
  saaSavePrefs();
});
saaHofToggle.addEventListener('change', () => { saaRender(); saaSavePrefs(); });
saaHofMissingToggle.addEventListener('change', () => {
  if (saaHofMissingToggle.checked) saaHofToggle.checked = false;
  saaHofToggle.disabled = saaHofMissingToggle.checked;
  saaExpanded.clear();
  saaRender();
  saaSizeScroll();
  saaSavePrefs();
});

// Click (or Enter/Space on a focused row) toggles that player's career card.
function saaToggleRow(tr) {
  const rank = Number(tr.dataset.rank);
  if (saaExpanded.has(rank)) saaExpanded.delete(rank);
  else saaExpanded.add(rank);
  saaRender();
  if (saaExpanded.has(rank)) {
    const again = saaTbody.querySelector(`tr.saa-row[data-rank="${rank}"]`);
    if (again) again.focus();
  }
}

saaTbody.addEventListener('click', e => {
  const tr = e.target.closest('tr.saa-row:not(.is-flat)');
  if (tr) saaToggleRow(tr);
});
saaTbody.addEventListener('keydown', e => {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  const tr = e.target.closest('tr.saa-row:not(.is-flat)');
  if (!tr) return;
  e.preventDefault();
  saaToggleRow(tr);
});

// Size the table window to ~15 data rows (plus the sticky header),
// so the list scrolls inside a fixed frame instead of running down the page.
const saaShell = document.querySelector('.saa-embed .table-shell');
function saaSizeScroll() {
  if (!saaShell) return;
  const head = saaShell.querySelector('thead');
  const row = saaShell.querySelector('tbody tr.saa-row');
  if (!head || !row) return;
  const h = head.getBoundingClientRect().height + row.getBoundingClientRect().height * 15;
  saaShell.style.maxHeight = Math.round(h) + 'px';
}

// "On the bubble" -- the 20 players just outside the cut. Static: not
// filtered by the search box or the Hall-of-Famers toggle.
function saaRenderBubble() {
  if (!saaBubbleEl || !SAA_BUBBLE.length) return;
  saaBubbleEl.innerHTML = SAA_BUBBLE.map(d => `
    <div class="bubble-row">
      <span class="bubble-rank">${d.rank}</span>
      <span class="bubble-name">${d.nel ? '<span class="nel-tag">NeL</span> ' : ''}${d.name}${d.hof ? ' <span class="hof-star">★</span>' : ''}</span>
      <span class="bubble-saa">${d.saa > 0 ? '+' : ''}${d.saa.toFixed(2)}</span>
    </div>`).join('');
}

saaRender();
saaRenderBubble();
saaSizeScroll();
if (document.fonts && document.fonts.ready) document.fonts.ready.then(saaSizeScroll);
window.addEventListener('resize', saaSizeScroll);
